  1	// Floating ball: a draggable desktop orb. Left-click opens a bubble menu,
  2	// right-click opens Settings, drag moves the window and persists its position
  3	// on release.
  4	
  5	import "./styles.css";
  6	
  7	import { invoke } from "@tauri-apps/api/core";
  8	import { emit, listen } from "@tauri-apps/api/event";
  9	import { cursorPosition, currentMonitor, getCurrentWindow, LogicalPosition, LogicalSize, PhysicalPosition } from "@tauri-apps/api/window";
 10	import { FloatingBallDragController } from "./floating-ball-drag";
 11	import { attachFloatingBallPointerDrag } from "./floating-ball-pointer";
 12	import { t, setLang, type Lang } from "./i18n";
 13	import { Pet } from "./pet";
 14	import { getLibrary } from "./catalog";
 15	import { loadPetStore, selectedPetInstance } from "./pets";
 16	
 17	const QUICK_KEY = "ap_quick_bubbles";
 18	const MAX_PRESETS = 12;
 19	
 20	const WIN_SIZE = 80;        // window is larger than the 56px orb so shadows/scale fit
 21	const MENU_W = 300;
 22	const MENU_H = 420;
 23	
 24	const ball = document.getElementById("ball") as HTMLDivElement;
 25	const menu = document.getElementById("ball-menu") as HTMLDivElement;
 26	const input = document.getElementById("bm-input") as HTMLInputElement;
 27	const presetsEl = document.getElementById("bm-presets") as HTMLDivElement;
 28	const sendBtn = document.getElementById("bm-send") as HTMLButtonElement;
 29	const cancelBtn = document.getElementById("bm-cancel") as HTMLButtonElement;
 30	
 31	const win = getCurrentWindow();
 32	const floatingBallDrag = new FloatingBallDragController({
 33	  cursorPosition,
 34	  setPosition: (position) => win.setPosition(new PhysicalPosition(position.x, position.y)),
 35	  persistPosition: () => invoke<void>("persist_floating_ball_position"),
 36	});
 37	
 38	let selectedPreset = -1;
 39	
 40	function readPresets(): string[] {
 41	  try {
 42	    const v = JSON.parse(localStorage.getItem(QUICK_KEY) || "[]");
 43	    return Array.isArray(v)
 44	      ? v.filter((x: unknown) => typeof x === "string" && x.trim()).slice(0, MAX_PRESETS)
 45	      : [];
 46	  } catch { return []; }
 47	}
 48	
 49	function writePresets(list: string[]) {
 50	  localStorage.setItem(QUICK_KEY, JSON.stringify(list.slice(0, MAX_PRESETS)));
 51	  void emit("bubble-changed", null);
 52	}
 53	
 54	function syncSend() {
 55	  sendBtn.disabled = !input.value.trim();
 56	}
 57	
 58	function createPresetButton(line: string, index: number) {
 59	  const btn = document.createElement("button");
 60	  btn.className = "bm-preset";
 61	  btn.textContent = line;
 62	  btn.title = t("Send to selected") + " · " + t("Shift-click to delete");
 63	  btn.onclick = (ev) => {
 64	    if (ev.shiftKey) {
 65	      const next = readPresets().filter((_, j) => j !== index);
 66	      writePresets(next);
 67	      selectedPreset = -1;
 68	      paintPresets();
 69	      syncSend();
 70	      return;
 71	    }
 72	    selectedPreset = index;
 73	    input.value = line;
 74	    paintPresets();
 75	    syncSend();
 76	    input.focus();
 77	  };
 78	  if (selectedPreset === index) btn.classList.add("sel");
 79	  return btn;
 80	}
 81	
 82	function paintPresets() {
 83	  const list = readPresets();
 84	  presetsEl.innerHTML = "";
 85	  if (!list.length) {
 86	    presetsEl.style.display = "none";
 87	    return;
 88	  }
 89	  presetsEl.style.display = "";
 90	  list.forEach((line, i) => presetsEl.appendChild(createPresetButton(line, i)));
 91	}
 92	
 93	function applyLangStrings() {
 94	  const bmTitle = document.getElementById("bm-title-text");
 95	  if (bmTitle) bmTitle.textContent = t("Quick bubble");
 96	  const bmHint = document.getElementById("bm-hint");
 97	  if (bmHint) bmHint.textContent = t("Shift-click to remove");
 98	  input.placeholder = t("Type a bubble message…");
 99	  cancelBtn.textContent = t("Cancel");
100	  sendBtn.textContent = t("Send");
101	  ball.title = t("Left-click: bubble · Right-click: settings · Drag to move");
102	}
103	
104	function shrinkToBall() {
105	  void win.setSize(new LogicalSize(WIN_SIZE, WIN_SIZE));
106	}
107	
108	/// Height delta between the menu window and the ball window.
109	const MENU_GROW = MENU_H - WIN_SIZE;
110	
111	async function showMenu() {
112	  if (!menu.hidden) return;
113	  input.value = "";
114	  selectedPreset = -1;
115	  paintPresets();
116	  syncSend();
117	
118	  const pos = await win.outerPosition();
119	  const sf = await win.scaleFactor();
120	  const mon = await currentMonitor();
121	  const work = mon?.workArea;
122	  const logicalX = pos.x / sf;
123	  const logicalY = pos.y / sf;
124	  const workLeft = work ? work.position.x / sf : logicalX;
125	  const workTop = work ? work.position.y / sf : logicalY;
126	  const workRight = work ? (work.position.x + work.size.width) / sf : logicalX + MENU_W;
127	  const workBottom = work ? (work.position.y + work.size.height) / sf : logicalY + MENU_H;
128	
129	  // If the menu would overflow the bottom, open UPWARD: the ball sticks to
130	  // the bottom of the window and the menu sits above it. The window's Y
131	  // moves up by MENU_GROW so the ball's screen position is preserved.
132	  const openAbove = logicalY + MENU_H > workBottom;
133	  // Adjust X so the wider menu window stays on-screen.
134	  let newX = logicalX;
135	  if (newX + MENU_W > workRight) newX = workRight - MENU_W;
136	  if (newX < workLeft) newX = workLeft;
137	  let newY = logicalY;
138	  if (openAbove) newY = logicalY - MENU_GROW;
139	  // Clamp Y so the window never starts above the work area.
140	  if (newY < workTop) newY = workTop;
141	
142	  document.body.classList.toggle("menu-above", openAbove);
143	  if (Math.abs(newX - logicalX) > 0.5 || Math.abs(newY - logicalY) > 0.5) {
144	    void win.setPosition(new LogicalPosition(newX, newY));
145	  }
146	  // Resize FIRST, then reveal the menu, so the menu never appears clipped
147	  // inside the still-80×80 window for a frame.
148	  await win.setSize(new LogicalSize(MENU_W, MENU_H));
149	  menu.hidden = false;
150	  requestAnimationFrame(() => input.focus());
151	}
152	
153	function hideMenu() {
154	  if (menu.hidden) return;
155	  menu.hidden = true;
156	  const wasAbove = document.body.classList.contains("menu-above");
157	  document.body.classList.remove("menu-above");
158	  shrinkToBall();
159	  if (wasAbove) {
160	    // Window was shifted up by MENU_GROW to open the menu above.
161	    // Move it back down so the ball returns to its original screen position.
162	    void (async () => {
163	      const pos = await win.outerPosition();
164	      const sf = await win.scaleFactor();
165	      void win.setPosition(new LogicalPosition(pos.x / sf, pos.y / sf + MENU_GROW));
166	    })();
167	  }
168	}
169	
170	function send() {
171	  const text = input.value.trim();
172	  if (!text) return;
173	  const next = [text, ...readPresets().filter((x) => x !== text)];
174	  writePresets(next);
175	  void emit("quick-bubble", { text });
176	  hideMenu();
177	}
178	
179	// ---- click vs drag ---------------------------------------------------------
180	// Tauri's native startDragging can lose mouseup on Windows, leaving the window
181	// attached to the cursor. Pointer capture keeps the interaction in the webview.
182	attachFloatingBallPointerDrag(ball, {
183	  drag: floatingBallDrag,
184	  isMenuOpen: () => !menu.hidden,
185	  hideMenu,
186	  showMenu,
187	  now: () => performance.now(),
188	  scale: () => window.devicePixelRatio,
189	  reportError: (error) => console.error("Unable to finish floating ball drag", error),
190	});
191	
192	ball.addEventListener("contextmenu", (e) => {
193	  e.preventDefault();
194	  hideMenu();
195	  void invoke("open_settings");
196	});
197	
198	// ---- menu interactions -----------------------------------------------------
199	input.addEventListener("input", () => { selectedPreset = -1; paintPresets(); syncSend(); });
200	input.addEventListener("keydown", (e) => {
201	  if (e.key === "Enter" && input.value.trim()) { e.preventDefault(); send(); }
202	  else if (e.key === "Escape") { hideMenu(); }
203	});
204	
205	cancelBtn.onclick = () => hideMenu();
206	sendBtn.onclick = () => send();
207	
208	// Dismiss menu on Escape or when the window loses focus.
209	window.addEventListener("keydown", (e) => { if (e.key === "Escape" && !menu.hidden) hideMenu(); });
210	window.addEventListener("blur", () => { if (!menu.hidden) hideMenu(); });
211	
212	// ---- live updates ----------------------------------------------------------
213	function applyReduceMotion() {
214	  document.body.classList.toggle("reduce-motion", localStorage.getItem("ap_reduce_motion") === "1");
215	}
216	applyReduceMotion();
217	window.addEventListener("storage", (e) => { if (e.key === "ap_reduce_motion") applyReduceMotion(); });
218	
219	applyLangStrings();
220	paintPresets();
  1	export type Point = {
  2	  x: number;
  3	  y: number;
  4	};
  5	
  6	export type PhysicalPoint = Point;
  7	
  8	export type FloatingBallDragHost = {
  9	  cursorPosition(): Promise<PhysicalPoint>;
 10	  setPosition(position: PhysicalPoint): Promise<void>;
 11	  persistPosition(): Promise<void>;
 12	};
 13	
 14	export type FloatingBallDragOutcome = {
 15	  kind: "click" | "drag" | "cancel";
 16	  completion: Promise<void> | null;
 17	};
 18	
 19	type ActiveDrag = {
 20	  pointerId: number;
 21	  startPoint: Point;
 22	  latestPoint: Point;
 23	  grabOffset: PhysicalPoint;
 24	  startedAt: number;
 25	  isDragging: boolean;
 26	  needsMove: boolean;
 27	  moveTask: Promise<void> | null;
 28	  firstMoveError: unknown | null;
 29	};
 30	
 31	export class FloatingBallDragController {
 32	  private active: ActiveDrag | null = null;
 33	
 34	  constructor(
 35	    private readonly host: FloatingBallDragHost,
 36	    private readonly thresholdPx = 4,
 37	    private readonly clickMaxMs = 280,
 38	  ) {}
 39	
 40	  get isDragging(): boolean {
 41	    return this.active?.isDragging ?? false;
 42	  }
 43	
 44	  begin(pointerId: number, point: Point, grabOffset: PhysicalPoint, startedAt: number): boolean {
 45	    if (this.active) return false;
 46	    this.active = {
 47	      pointerId,
 48	      startPoint: point,
 49	      latestPoint: point,
 50	      grabOffset,
 51	      startedAt,
 52	      isDragging: false,
 53	      needsMove: false,
 54	      moveTask: null,
 55	      firstMoveError: null,
 56	    };
 57	    return true;
 58	  }
 59	
 60	  move(pointerId: number, point: Point): boolean {
 61	    const drag = this.active;
 62	    if (!drag || drag.pointerId !== pointerId) return false;
 63	    drag.latestPoint = point;
 64	    if (!drag.isDragging && this.movedBeyondThreshold(drag)) {
 65	      this.start(drag);
 66	      return true;
 67	    }
 68	    if (drag.isDragging) this.queueMove(drag);
 69	    return false;
 70	  }
 71	
 72	  finish(
 73	    pointerId: number,
 74	    point: Point,
 75	    allowClick: boolean,
 76	    now: number,
 77	  ): FloatingBallDragOutcome | null {
 78	    const drag = this.active;
 79	    if (!drag || drag.pointerId !== pointerId) return null;
 80	
 81	    drag.latestPoint = point;
 82	    this.active = null;
 83	    if (!drag.isDragging && this.movedBeyondThreshold(drag)) this.start(drag);
 84	    if (!drag.isDragging) {
 85	      return {
 86	        kind: allowClick && now - drag.startedAt <= this.clickMaxMs ? "click" : "cancel",
 87	        completion: null,
 88	      };
 89	    }
 90	
 91	    this.queueMove(drag);
 92	    return { kind: "drag", completion: this.persistAfterFinalMove(drag) };
 93	  }
 94	
 95	  private movedBeyondThreshold(drag: ActiveDrag): boolean {
 96	    return Math.abs(drag.latestPoint.x - drag.startPoint.x) > this.thresholdPx
 97	      || Math.abs(drag.latestPoint.y - drag.startPoint.y) > this.thresholdPx;
 98	  }
 99	
100	  private start(drag: ActiveDrag): void {
101	    drag.isDragging = true;
102	    this.queueMove(drag);
103	  }
104	
105	  private queueMove(drag: ActiveDrag): void {
106	    drag.needsMove = true;
107	    if (drag.moveTask) return;
108	
109	    const task = this.moveToLatestCursorPosition(drag);
110	    drag.moveTask = task;
111	    void task.then(
112	      () => { if (drag.moveTask === task) drag.moveTask = null; },
113	      (error) => {
114	        if (drag.firstMoveError === null) drag.firstMoveError = error;
115	        if (drag.moveTask === task) drag.moveTask = null;
116	      },
117	    );
118	  }
119	
120	  private async moveToLatestCursorPosition(drag: ActiveDrag): Promise<void> {
121	    while (drag.needsMove) {
122	      drag.needsMove = false;
123	      const cursor = await this.host.cursorPosition();
124	      await this.host.setPosition({
125	        x: cursor.x - drag.grabOffset.x,
126	        y: cursor.y - drag.grabOffset.y,
127	      });
128	    }
129	  }
130	
131	  private async persistAfterFinalMove(drag: ActiveDrag): Promise<void> {
132	    const finalMove = drag.moveTask;
133	    if (finalMove) await finalMove;
134	    await this.host.persistPosition();
135	    if (drag.firstMoveError !== null) throw drag.firstMoveError;
136	  }
137	}
  1	import type { FloatingBallDragOutcome, PhysicalPoint, Point } from "./floating-ball-drag";
  2	
  3	export type FloatingBallPointerDrag = {
  4	  begin(pointerId: number, point: Point, grabOffset: PhysicalPoint, startedAt: number): boolean;
  5	  move(pointerId: number, point: Point): boolean;
  6	  finish(pointerId: number, point: Point, allowClick: boolean, now: number): FloatingBallDragOutcome | null;
  7	};
  8	
  9	export type FloatingBallPointerOptions = {
 10	  drag: FloatingBallPointerDrag;
 11	  isMenuOpen(): boolean;
 12	  hideMenu(): void;
 13	  showMenu(): void;
 14	  now(): number;
 15	  scale(): number;
 16	  reportError(error: unknown): void;
 17	};
 18	
 19	function gesturePoint(e: PointerEvent): Point {
 20	  return { x: e.screenX, y: e.screenY };
 21	}
 22	
 23	function physicalGrabOffset(e: PointerEvent, scale: number): PhysicalPoint {
 24	  return { x: e.clientX * scale, y: e.clientY * scale };
 25	}
 26	
 27	export function attachFloatingBallPointerDrag(ball: HTMLElement, options: FloatingBallPointerOptions): void {
 28	  let activePointerId: number | null = null;
 29	
 30	  function finish(e: PointerEvent, allowClick: boolean): void {
 31	    if (activePointerId !== e.pointerId) return;
 32	    const outcome = options.drag.finish(e.pointerId, gesturePoint(e), allowClick, options.now());
 33	    activePointerId = null;
 34	    ball.classList.remove("pressed", "dragging");
 35	    if (ball.hasPointerCapture(e.pointerId)) ball.releasePointerCapture(e.pointerId);
 36	    if (!outcome) return;
 37	    if (outcome.kind === "click") {
 38	      options.showMenu();
 39	      return;
 40	    }
 41	    if (outcome.completion) void outcome.completion.catch(options.reportError);
 42	  }
 43	
 44	  ball.addEventListener("pointerdown", (e) => {
 45	    if (e.button !== 0) return;
 46	    if (options.isMenuOpen()) {
 47	      options.hideMenu();
 48	      return;
 49	    }
 50	    if (activePointerId !== null) return;
 51	
 52	    e.preventDefault();
 53	    if (!options.drag.begin(e.pointerId, gesturePoint(e), physicalGrabOffset(e, options.scale()), options.now())) return;
 54	    activePointerId = e.pointerId;
 55	    ball.setPointerCapture(e.pointerId);
 56	    ball.classList.add("pressed");
 57	  });
 58	
 59	  ball.addEventListener("pointermove", (e) => {
 60	    if (activePointerId !== e.pointerId) return;
 61	    if (options.drag.move(e.pointerId, gesturePoint(e))) {
 62	      ball.classList.remove("pressed");
 63	      ball.classList.add("dragging");
 64	    }
 65	  });
 66	
 67	  ball.addEventListener("pointerup", (e) => finish(e, true));
 68	  ball.addEventListener("pointercancel", (e) => finish(e, false));
 69	  ball.addEventListener("lostpointercapture", (e) => finish(e, false));
 70	}
